        let ENABLED = self.ENABLED;
        let GENERATED_AT_MS = self.GENERATED_AT_MS;
        let RETRIEVED_COUNT = self.RETRIEVED_COUNT;
        let COMPLETED_COUNT = self.COMPLETED_COUNT;
