pub struct SRGBuilder<'a: 'b, 'b, A: ::flatbuffers::Allocator + 'a> {
    fbb_: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    start_: ::flatbuffers::WIPOffset<::flatbuffers::TableUnfinishedWIPOffset>,
}

impl<'a: 'b, 'b, A: ::flatbuffers::Allocator + 'a> SRGBuilder<'a, 'b, A> {
    #[inline]
    pub fn add_REGISTRY_ID(&mut self, REGISTRY_ID: ::flatbuffers::WIPOffset<&'b  str>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<_>>(SRG::VT_REGISTRY_ID, REGISTRY_ID);
    }

    #[inline]
    pub fn add_UPSTREAM_REPOSITORY(&mut self, UPSTREAM_REPOSITORY: ::flatbuffers::WIPOffset<&'b  str>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<_>>(SRG::VT_UPSTREAM_REPOSITORY, UPSTREAM_REPOSITORY);
    }

    #[inline]
    pub fn add_UPSTREAM_REVISION(&mut self, UPSTREAM_REVISION: ::flatbuffers::WIPOffset<&'b  str>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<_>>(SRG::VT_UPSTREAM_REVISION, UPSTREAM_REVISION);
    }

    #[inline]
    pub fn add_REGISTRY_PATH(&mut self, REGISTRY_PATH: ::flatbuffers::WIPOffset<&'b  str>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<_>>(SRG::VT_REGISTRY_PATH, REGISTRY_PATH);
    }

    #[inline]
    pub fn add_GENERATED_AT_MS(&mut self, GENERATED_AT_MS: i64) {
        self.fbb_.push_slot::<i64>(SRG::VT_GENERATED_AT_MS, GENERATED_AT_MS, 0);
    }

    #[inline]
    pub fn add_PROVIDERS(&mut self, PROVIDERS: ::flatbuffers::WIPOffset<::flatbuffers::Vector<'b , ::flatbuffers::ForwardsUOffset<SRGProvider<'b >>>>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<_>>(SRG::VT_PROVIDERS, PROVIDERS);
    }

    #[inline]
    pub fn add_RESOURCES(&mut self, RESOURCES: ::flatbuffers::WIPOffset<::flatbuffers::Vector<'b , ::flatbuffers::ForwardsUOffset<SRGResource<'b >>>>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<_>>(SRG::VT_RESOURCES, RESOURCES);
    }

    #[inline]
    pub fn add_RECEIPTS(&mut self, RECEIPTS: ::flatbuffers::WIPOffset<::flatbuffers::Vector<'b , ::flatbuffers::ForwardsUOffset<SRGContentReceipt<'b >>>>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<_>>(SRG::VT_RECEIPTS, RECEIPTS);
    }

    #[inline]
    pub fn add_STATUS(&mut self, STATUS: ::flatbuffers::WIPOffset<SRGRetrievalStatus<'b >>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<SRGRetrievalStatus>>(SRG::VT_STATUS, STATUS);
    }

    #[inline]
    pub fn add_SETTINGS(&mut self, SETTINGS: ::flatbuffers::WIPOffset<SRGRetrievalSettings<'b >>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<SRGRetrievalSettings>>(SRG::VT_SETTINGS, SETTINGS);
    }

    #[inline]
    pub fn new(_fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>) -> SRGBuilder<'a, 'b, A> {
        let start = _fbb.start_table();
        SRGBuilder {
            fbb_: _fbb,
            start_: start,
        }
    }

    #[inline]
    pub fn finish(self) -> ::flatbuffers::WIPOffset<SRG<'a>> {
        let o = self.fbb_.end_table(self.start_);
        ::flatbuffers::WIPOffset::new(o.value())
    }
}

