#[non_exhaustive]
#[derive(Debug, Clone, PartialEq)]
pub struct SRGT {
    pub REGISTRY_ID: Option<alloc::string::String>,
    pub UPSTREAM_REPOSITORY: Option<alloc::string::String>,
    pub UPSTREAM_REVISION: Option<alloc::string::String>,
    pub REGISTRY_PATH: Option<alloc::string::String>,
    pub GENERATED_AT_MS: i64,
    pub PROVIDERS: Option<alloc::vec::Vec<SRGProviderT>>,
    pub RESOURCES: Option<alloc::vec::Vec<SRGResourceT>>,
    pub RECEIPTS: Option<alloc::vec::Vec<SRGContentReceiptT>>,
    pub STATUS: Option<alloc::boxed::Box<SRGRetrievalStatusT>>,
    pub SETTINGS: Option<alloc::boxed::Box<SRGRetrievalSettingsT>>,
}

impl Default for SRGT {
    fn default() -> Self {
        Self {
            REGISTRY_ID: None,
            UPSTREAM_REPOSITORY: None,
            UPSTREAM_REVISION: None,
            REGISTRY_PATH: None,
            GENERATED_AT_MS: 0,
            PROVIDERS: None,
            RESOURCES: None,
            RECEIPTS: None,
            STATUS: None,
            SETTINGS: None,
        }
    }
}

impl SRGT {
    pub fn pack<'b, A: ::flatbuffers::Allocator + 'b>(
        &self,
        _fbb: &mut ::flatbuffers::FlatBufferBuilder<'b, A>
    ) -> ::flatbuffers::WIPOffset<SRG<'b>> {
        let REGISTRY_ID = self.REGISTRY_ID.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        let UPSTREAM_REPOSITORY = self.UPSTREAM_REPOSITORY.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        let UPSTREAM_REVISION = self.UPSTREAM_REVISION.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        let REGISTRY_PATH = self.REGISTRY_PATH.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        let GENERATED_AT_MS = self.GENERATED_AT_MS;
        let PROVIDERS = self.PROVIDERS.as_ref().map(|x|{
            let w: alloc::vec::Vec<_> = x.iter().map(|t| t.pack(_fbb)).collect();_fbb.create_vector(&w)
        });
        let RESOURCES = self.RESOURCES.as_ref().map(|x|{
            let w: alloc::vec::Vec<_> = x.iter().map(|t| t.pack(_fbb)).collect();_fbb.create_vector(&w)
        });
        let RECEIPTS = self.RECEIPTS.as_ref().map(|x|{
            let w: alloc::vec::Vec<_> = x.iter().map(|t| t.pack(_fbb)).collect();_fbb.create_vector(&w)
        });
        let STATUS = self.STATUS.as_ref().map(|x|{
            x.pack(_fbb)
        });
        let SETTINGS = self.SETTINGS.as_ref().map(|x|{
            x.pack(_fbb)
        });
        SRG::create(_fbb, &SRGArgs{
            REGISTRY_ID,
            UPSTREAM_REPOSITORY,
            UPSTREAM_REVISION,
            REGISTRY_PATH,
            GENERATED_AT_MS,
            PROVIDERS,
            RESOURCES,
            RECEIPTS,
            STATUS,
            SETTINGS,
        })
    }
}

