/// `root_as_srg_unchecked`.
#[inline]
pub fn size_prefixed_root_as_srg_with_opts<'b, 'o>(
    opts: &'o ::flatbuffers::VerifierOptions,
    buf: &'b [u8],
) -> Result<SRG<'b>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::size_prefixed_root_with_opts::<SRG<'b>>(opts, buf)
}

/// Assumes, without verification, that a buffer of bytes contains a SRG and returns it.
/// # Safety
/// Callers must trust the given bytes do indeed contain a valid `SRG`.
#[inline]
pub unsafe fn root_as_srg_unchecked(buf: &[u8]) -> SRG<'_> {
    unsafe { ::flatbuffers::root_unchecked::<SRG>(buf) }
}

/// Assumes, without verification, that a buffer of bytes contains a size prefixed SRG and returns it.
/// # Safety
/// Callers must trust the given bytes do indeed contain a valid size prefixed `SRG`.
#[inline]
pub unsafe fn size_prefixed_root_as_srg_unchecked(buf: &[u8]) -> SRG<'_> {
    unsafe { ::flatbuffers::size_prefixed_root_unchecked::<SRG>(buf) }
}

pub const SRG_IDENTIFIER: &str = "$SRG";

#[inline]
pub fn srg_buffer_has_identifier(buf: &[u8]) -> bool {
    ::flatbuffers::buffer_has_identifier(buf, SRG_IDENTIFIER, false)
}

#[inline]
pub fn srg_size_prefixed_buffer_has_identifier(buf: &[u8]) -> bool {
    ::flatbuffers::buffer_has_identifier(buf, SRG_IDENTIFIER, true)
}

#[inline]
pub fn finish_srg_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(
    fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    root: ::flatbuffers::WIPOffset<SRG<'a>>
) {
    fbb.finish(root, Some(SRG_IDENTIFIER));
}

#[inline]
pub fn finish_size_prefixed_srg_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(
    fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    root: ::flatbuffers::WIPOffset<SRG<'a>>
) {
    fbb.finish_size_prefixed(root, Some(SRG_IDENTIFIER));
}
